extra_script:
// Önce ziyaretçinin kendi platformu; masaüstü ikisini de görür.
(function () {
  var ua = navigator.userAgent || "";
  var ios = /iPhone|iPad|iPod/.test(ua), android = /Android/.test(ua);
  if (ios) document.getElementById("android").style.display = "none";
  if (android) document.getElementById("ios").style.display = "none";
})();
// Links come from the admin panel (Firestore config/app), so a new
// TestFlight or Play link needs no new page.
fetch("https://firestore.googleapis.com/v1/projects/matchday-bamtech/databases/(default)/documents/config/app?key=AIzaSyDWl7gAoXzKTTK5su2J56W1-_rTJ6shr_E")
  .then(function (r) { return r.ok ? r.json() : null; })
  .then(function (d) {
    var f = d && d.fields;
    if (!f) return;
    if (f.iosURL && f.iosURL.stringValue) document.getElementById("iosLink").href = f.iosURL.stringValue;
    if (f.androidURL && f.androidURL.stringValue) document.getElementById("androidLink").href = f.androidURL.stringValue;
  })
  .catch(function () {});
